"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 1 (P1 v0.4, section 5.2): door sounds uploaded to Freesound after 2023-06-01, for test and
replication only (the FSD50K door pool is small). Reported separately by source (plan 7.5).

search:   door queries, created on or after 2023-06-01, CC0 or CC BY 3.0/4.0, 0.5-30 s, curated from title, tags and
          description with the door rules of step0v4_new_classes.py (house or room doors only; kind open, close, both
          or unknown) plus the v0.3 contamination rule (no other named sound source, no footsteps).
download: originals (OAuth), into data/freesound_doors/raw.
check:    fingerprints against every FSD50K clip we use, MUSAN noise, the Commons test clips and the v0.3 Freesound
          subset; any match is dropped (an old sound re-uploaded is not new).
assign:   an uploader already in a split keeps it (only test or replication are allowed; train or dev uploaders are
          dropped); new uploaders go to test or replication 2:1 (seeded), as the v0.3 Freesound subset.
usage: python -I scripts/step0v4_freesound_doors.py search|download|check|assign
"""
import glob
import json
import os
import random
import re
import sys
import time
import urllib.error
from collections import Counter

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import freesound_client as FS  # noqa: E402
import step0v4_new_classes as NC  # noqa: E402

OUT_DIR = "data/freesound_doors"
CAND = "results/step0_v04/freesound_doors_candidates.json"
RESULT = "results/step0_v04/freesound_doors.json"
QUERIES = ["door open", "door opening", "door close", "door closing", "front door", "door creak", "door latch",
           "wooden door", "door handle", "door squeak"]
FILTER = 'created:[2023-06-01T00:00:00Z TO *] duration:[0.5 TO 30]'
OK_LICENSE = re.compile(r"creativecommons\.org/(publicdomain/zero/1\.0|licenses/by/[34]\.0)/?$")
CONTAM = re.compile(r"\bdogs?\b|bark|speech|talk|voice|conversation|music|song|ambien|street|traffic|crowd|rain|"
                    r"wind\b|birds?\b|\btv\b|television|radio|laugh|scream|footstep", re.I)
MAX_FSD50K_ID = 452000
SEED = 20261115


def search():
    seen, cands = set(), {}
    for q in QUERIES:
        page = 1
        while True:
            st, js = FS.get("/search/", params={"query": q, "filter": FILTER, "page": page, "page_size": 150,
                                                "fields": "id,name,tags,description,license,username,created,"
                                                          "duration,type,samplerate,channels"})
            for s in js.get("results", []):
                if s["id"] in seen or not OK_LICENSE.search(s["license"]) or s["id"] < MAX_FSD50K_ID:
                    continue
                seen.add(s["id"])
                text = " ".join([s["name"], " ".join(s["tags"]), s.get("description", "")]).lower().replace("_", " ")
                if CONTAM.search(text) or NC.DOOR_EXCL.search(text) or not re.search(r"\bdoors?\b", text):
                    continue
                o, c = bool(NC.OPEN.search(text)), bool(NC.CLOSE.search(text))
                kind = "both" if o and c else "open" if o else "close" if c else "unknown"
                cands[str(s["id"])] = {"kind": kind, "query": q, "title": s["name"], "uploader": s["username"],
                                       "license": s["license"], "created": s["created"], "duration": s["duration"],
                                       "type": s["type"]}
            if not js.get("next") or page >= 6:
                break
            page += 1
            time.sleep(1.1)
        time.sleep(1.1)
    os.makedirs(os.path.dirname(CAND), exist_ok=True)
    json.dump(cands, open(CAND, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print("candidates:", len(cands), dict(Counter(v["kind"] for v in cands.values())),
          "uploaders:", len({v["uploader"] for v in cands.values()}))


def download():
    cands = json.load(open(CAND, encoding="utf-8"))
    raw = os.path.join(OUT_DIR, "raw")
    os.makedirs(raw, exist_ok=True)
    done = {os.path.splitext(f)[0] for f in os.listdir(raw)}
    n = 0
    for sid, v in cands.items():
        if sid in done or v["type"] in ("m4a",):
            continue
        for attempt in range(3):
            try:
                st, data = FS.get(f"/sounds/{sid}/download/", oauth=True, raw=True)
                open(os.path.join(raw, f"{sid}.{v['type']}"), "wb").write(data)
                n += 1
                break
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    time.sleep(60)
                elif attempt == 2:
                    print("failed", sid, e.code)
        time.sleep(1.1)
    print("downloaded", n, "files; total in raw:", len(os.listdir(raw)))


def check():
    import step0_fingerprint as F
    cands = json.load(open(CAND, encoding="utf-8"))
    thr = json.load(open("results/step0/fingerprint_groups.json", encoding="utf-8"))["threshold_aligned_matches"]
    ref = (sorted(glob.glob("data/fsd50k_sel/*.wav")) + sorted(glob.glob("data/musan_dl/musan/noise/*/*.wav"))
           + sorted(glob.glob("data/commons4_testonly/*")) + sorted(glob.glob("data/freesound_new/raw/*")))
    index = F.Index([F.fingerprint(F.load(p)) for p in ref])
    files = {os.path.splitext(os.path.basename(p))[0]: p for p in glob.glob(os.path.join(OUT_DIR, "raw", "*"))}
    keep, dropped = {}, {}
    fps = {}
    for sid, p in sorted(files.items()):
        try:
            y = F.load(p)
        except Exception as e:  # noqa: BLE001
            dropped[sid] = f"unreadable ({type(e).__name__})"
            continue
        fps[sid] = F.fingerprint(y)
        best = index.best(*fps[sid])
        hit = max(best.items(), key=lambda kv: kv[1], default=(None, 0))
        if hit[1] >= thr:
            dropped[sid] = f"matches {os.path.basename(ref[hit[0]])} ({hit[1]})"
        else:
            keep[sid] = cands[sid]
    ids = sorted(keep, key=int)
    own = F.Index([fps[k] for k in ids])
    links = [(ids[a], ids[j], int(c)) for a, k in enumerate(ids)
             for j, c in own.best(*fps[k], exclude=a).items() if c >= thr]
    json.dump({"threshold": thr, "kept": keep, "dropped": dropped, "links": links},
              open(RESULT, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print("kept", len(keep), dict(Counter(v["kind"] for v in keep.values())), "dropped", len(dropped),
          "same-sound links among kept", len(links))


def assign():
    res = json.load(open(RESULT, encoding="utf-8"))
    keep = res["kept"]
    ns = json.load(open("results/step0_v04/new_split.json", encoding="utf-8"))
    fin = json.load(open("results/step0/split_final.json", encoding="utf-8"))
    oldsel = json.load(open("results/step0/fsd50k_selection.json", encoding="utf-8"))
    pools = json.load(open("results/step0/event_decoy_pools.json", encoding="utf-8"))["clips"]
    fsnew = json.load(open("results/step0/freesound_new_subset.json", encoding="utf-8"))["kept"]
    up_split = {}
    for k, m in fin["manifest"].items():
        up = (pools.get(k) or oldsel.get(k) or {}).get("uploader")
        if up and m["split"] != "excluded":
            up_split.setdefault(up, set()).add(m["split"])
    for k, m in ns["manifest"].items():
        up_split.setdefault(m["uploader"], set()).add(m["split"])
    for k, v in fsnew.items():
        if k not in ns["freesound_new_excluded_in_v04"]:
            up_split.setdefault(v["uploader"], set()).add(v["split"])
    parent = {k: k for k in keep}

    def root(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    by_up = {}
    for k in sorted(keep, key=int):
        by_up.setdefault(keep[k]["uploader"], []).append(k)
    for ks in by_up.values():
        for k in ks[1:]:
            parent[root(k)] = root(ks[0])
    for a, b, _ in res["links"]:
        parent[root(a)] = root(b)
    groups = {}
    for k in keep:
        groups.setdefault(root(k), []).append(k)
    split_of = {}
    free = []
    for g, ks in sorted(groups.items(), key=lambda kv: int(kv[0])):
        known = set().union(*(up_split.get(keep[k]["uploader"], set()) for k in ks))
        if not known:
            free.append(g)
        elif known <= {"test"} or known <= {"replication"}:
            split_of[g] = known.pop()
        else:
            split_of[g] = "excluded"
    rng = random.Random(SEED)
    rng.shuffle(free)
    for i, g in enumerate(free):
        split_of[g] = "test" if i % 3 != 2 else "replication"
    manifest = {k: {"kind": keep[k]["kind"], "uploader": keep[k]["uploader"], "group": f"f{root(k)}",
                    "split": split_of[root(k)]} for k in keep}
    table = {sp: {"clips": sum(m["split"] == sp for m in manifest.values()),
                  "groups": len({m["group"] for m in manifest.values() if m["split"] == sp}),
                  "kinds": dict(Counter(m["kind"] for m in manifest.values() if m["split"] == sp))}
             for sp in ("test", "replication", "excluded")}
    res["assign"] = {"seed": SEED, "table": table, "manifest": manifest}
    json.dump(res, open(RESULT, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print(table)


if __name__ == "__main__":
    {"search": search, "download": download, "check": check, "assign": assign}[sys.argv[1]]()
